val token = primary.createStatement().use { st ->
    st.executeQuery("SELECT pg_current_wal_lsn()::text").use { rs -> rs.next(); rs.getString(1) }
}
session.lastWritten = token                  // stored with the user's session

// before a read: is the standby there yet?
val caughtUp = standby.prepareStatement(
    "SELECT pg_last_wal_replay_lsn() >= ?::pg_lsn"
).use { ps ->
    ps.setString(1, session.lastWritten)
    ps.executeQuery().use { rs -> rs.next(); rs.getBoolean(1) }
}
val conn = if (caughtUp) standby else primary

