data class ReadToken(val lastWritten: Long = 0, val lastSeen: Long = 0) {
    val floor: Long get() = maxOf(lastWritten, lastSeen)   // never read below this
}

fun route(t: ReadToken, sticky: Replica, others: List<Replica>, leader: Node): Node =
    (listOf(sticky) + others)
        .filter { it.alive }
        .firstOrNull { it.position() >= t.floor }
        ?: leader.also { metrics.leaderReads.increment() }
